	/* @Test */
	public void testStringMapAtNoAddress()
    {
		TracePropertyMap<string> map;
		using (Transaction tx = tb.startTransaction())
{
			map = propertyManager.createPropertyMap("MyProp", typeof(string));

			map.set(Lifespan.nowOn(0), Address.NO_ADDRESS, "Value");
		}

		assertEquals("Value", map.get(4, Address.NO_ADDRESS));

		File file = tb.save();

		using (ToyDBTraceBuilder tb = new ToyDBTraceBuilder(file))
{
			TracePropertyMap<string> map2 =
				tb.trace.getAddressPropertyManager().getPropertyMap("MyProp", typeof(string));
			assertEquals("Value", map2.get(4, Address.NO_ADDRESS));
		}
	}
